export const ALL_VOCABULARY: VocabularyItem[] = RAW_VOCABULARY.map((item) => {
  const part: 1 | 2 = item.lesson <= 15 ? 1 : 2;
  const hasKanji = item.hanViet.trim().length > 0 || containsKanji(item.word);
  return {
    ...item,
    part,
    hasKanji,
  };
});
